import { useNavigate } from "react-router-dom";

function Dashboard() {
  const nav = useNavigate();

  return (
    <div>
      <h1>Dashboard</h1>

      <button onClick={() => nav("/donate")}>Donate</button>
      <button onClick={() => nav("/buy")}>Buy</button>
      <button onClick={() => nav("/sell")}>Sell</button>
    </div>
  );
}

export default Dashboard;
